//! Who wrote the prompt a turn starts from.
//!
//! No other harness tells hooks whether a prompt came from a person or was
//! generated by the host. jcode does, so workflow frameworks never have to
//! reverse-engineer it from transcripts. The vocabulary:
//!
//! | `origin_detail` | Meaning |
//! |---|---|
//! | `user` | typed in a client, or the `jcode run` message |
//! | `auto` | client auto-poke, retry, client system sends |
//! | `reminder` | reminder-only turn (`[auto]` continuation) |
//! | `swarm_message` | DM or channel wake from another agent |
//! | `swarm_spawn` | a worker's initial prompt |
//! | `background_task` | background task completion wake |
//! | `system` | server-generated system turn |
//! | `sdk` | harness API client |

use serde_json::{Value, json};
use std::collections::HashMap;
use std::sync::{LazyLock, Mutex};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PromptOrigin {
    User,
    Auto,
    Reminder,
    SwarmMessage,
    SwarmSpawn,
    BackgroundTask,
    System,
    Sdk,
}

impl PromptOrigin {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::User => "user",
            Self::Auto => "auto",
            Self::Reminder => "reminder",
            Self::SwarmMessage => "swarm_message",
            Self::SwarmSpawn => "swarm_spawn",
            Self::BackgroundTask => "background_task",
            Self::System => "system",
            Self::Sdk => "sdk",
        }
    }

    /// Parse the wire/env name. Unknown names are not accepted, so a client
    /// cannot invent a new origin that downstream tools would misread.
    pub fn parse(name: &str) -> Option<Self> {
        Some(match name.trim() {
            "user" => Self::User,
            "auto" => Self::Auto,
            "reminder" => Self::Reminder,
            "swarm_message" => Self::SwarmMessage,
            "swarm_spawn" => Self::SwarmSpawn,
            "background_task" => Self::BackgroundTask,
            "system" => Self::System,
            "sdk" => Self::Sdk,
            _ => return None,
        })
    }

    /// Only a person typing mints human presence.
    pub fn is_person(self) -> bool {
        self == Self::User
    }

    /// Top-level `origin` object, in the shape AI-DLC's `TurnOrigin` reads.
    pub fn turn_origin_json(self) -> Value {
        if self.is_person() {
            json!({"kind": "person"})
        } else {
            json!({"kind": "host", "reason": self.as_str(), "source": "record"})
        }
    }
}

#[derive(Default)]
struct SessionOrigins {
    pending: Option<PromptOrigin>,
    current: Option<PromptOrigin>,
}

static ORIGINS: LazyLock<Mutex<HashMap<String, SessionOrigins>>> =
    LazyLock::new(|| Mutex::new(HashMap::new()));

/// Declare the origin of the next prompt in `session_id`. Consumed by
/// [`begin_turn_origin`].
pub fn set_pending_prompt_origin(session_id: &str, origin: PromptOrigin) {
    ORIGINS
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .entry(session_id.to_owned())
        .or_default()
        .pending = Some(origin);
}

/// [`set_pending_prompt_origin`] from a wire name; unknown or absent names change nothing.
pub fn set_pending_prompt_origin_named(session_id: &str, name: Option<&str>) {
    if let Some(origin) = name.and_then(PromptOrigin::parse) {
        set_pending_prompt_origin(session_id, origin);
    }
}

/// Start a turn: take the pending origin (else `default`) and remember it as
/// the turn's origin for later hooks (`turn_start`, `stop`).
pub fn begin_turn_origin(session_id: &str, default: PromptOrigin) -> PromptOrigin {
    let mut origins = ORIGINS.lock().unwrap_or_else(|e| e.into_inner());
    let entry = origins.entry(session_id.to_owned()).or_default();
    let origin = entry.pending.take().unwrap_or(default);
    entry.current = Some(origin);
    origin
}

/// Origin of the turn currently running in `session_id`, if any.
pub fn current_prompt_origin(session_id: &str) -> Option<PromptOrigin> {
    ORIGINS
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .get(session_id)
        .and_then(|entry| entry.current)
}

/// Forget a session's origins.
pub fn forget_prompt_origin(session_id: &str) {
    ORIGINS
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .remove(session_id);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_round_trip_and_unknown_is_rejected() {
        for origin in [
            PromptOrigin::User,
            PromptOrigin::Auto,
            PromptOrigin::Reminder,
            PromptOrigin::SwarmMessage,
            PromptOrigin::SwarmSpawn,
            PromptOrigin::BackgroundTask,
            PromptOrigin::System,
            PromptOrigin::Sdk,
        ] {
            assert_eq!(PromptOrigin::parse(origin.as_str()), Some(origin));
        }
        assert_eq!(PromptOrigin::parse("person"), None);
    }

    #[test]
    fn only_user_is_a_person_in_turn_origin_shape() {
        assert_eq!(
            PromptOrigin::User.turn_origin_json(),
            json!({"kind": "person"})
        );
        assert_eq!(
            PromptOrigin::SwarmSpawn.turn_origin_json(),
            json!({"kind": "host", "reason": "swarm_spawn", "source": "record"})
        );
    }

    #[test]
    fn pending_is_consumed_once_and_current_persists() {
        let id = "origin-test-session";
        set_pending_prompt_origin(id, PromptOrigin::Auto);
        assert_eq!(
            begin_turn_origin(id, PromptOrigin::User),
            PromptOrigin::Auto
        );
        assert_eq!(current_prompt_origin(id), Some(PromptOrigin::Auto));
        assert_eq!(
            begin_turn_origin(id, PromptOrigin::User),
            PromptOrigin::User
        );
        forget_prompt_origin(id);
        assert_eq!(current_prompt_origin(id), None);
    }
}
